const raw = $input.first().json.stdout;
let data;

try {
  data = JSON.parse(raw);
} catch (e) {
  data = {
    fatal: `Impossibile parsare output SSH: ${e.message}`,
    manifest: [], updates: [], errors: [],
    unchanged: [], untracked_warnings: [],
    run_at: new Date().toISOString(),
    summary: { has_fatal: true }
  };
}

// Normalizza: aggiunge has_fatal se lo script l'ha emesso alla radice
if (data.fatal && !data.summary?.has_fatal) {
  data.summary = { ...data.summary, has_fatal: true };
}

return [{ json: data }];

const data = $input.first().json;
const notifications = [];
const runTime = data.run_at?.slice(0, 16).replace('T', ' ') + ' UTC' || 'N/A';

// ── 1. FATAL: qualcosa di grave ha impedito il check ─────────────────────────
if (data.summary?.has_fatal || data.fatal) {
  notifications.push({
    title: 'Homelab - Update Checker Failed',
    priority: 'urgent',
    tags: 'rotating_light',
    body: `🚨 Il check degli aggiornamenti ha fallito completamente.\n\n❌ ${data.fatal || 'Errore sconosciuto'}\n\n⏱ ${runTime}`
  });
  return notifications.map(n => ({ json: n }));
}

// ── 2. ERRORI RSS ─────────────────────────────────────────────────────────────
if (data.errors?.length > 0) {
  const hasCritical = data.errors.some(e => e.criticality === 'critical');
  const lines = data.errors.map(e =>
    `• ${e.display_name}  [${e.criticality} · ${e.stack_name}]\n  ↳ ${e.error_detail}`
  ).join('\n\n');

  notifications.push({
    title: `Homelab Updates - ${data.errors.length} errore/i RSS`,
    priority: hasCritical ? 'high' : 'default',
    tags: 'warning',
    body: `⚠️ Errori nel controllo aggiornamenti (${runTime}):\n\n${lines}`
  });
}

// ── 3. AGGIORNAMENTI DISPONIBILI ──────────────────────────────────────────────
if (data.updates?.length > 0) {
  const HIGH_DRIFT_THRESHOLD = 50;

  const hasMajorOrCritical = data.updates.some(
    u => u.is_major_bump || u.criticality === 'critical'
  );
  const hasHighDrift = data.updates.some(
    u => (u.version_gap ?? 0) >= HIGH_DRIFT_THRESHOLD
  );

  const lines = data.updates
    .sort((a, b) => {
      // Ordinamento primario: version_gap (più alto = più urgente)
      // Secondario: criticality, poi bump_type
      const gapDiff = (b.version_gap ?? 0) - (a.version_gap ?? 0);
      if (gapDiff !== 0) return gapDiff;
      const critOrder = { critical: 0, medium: 1, low: 2, stateless: 3 };
      const bumpOrder = { major: 0, minor: 1, patch: 2, unknown: 3 };
      return (critOrder[a.criticality] ?? 9) - (critOrder[b.criticality] ?? 9)
          || (bumpOrder[a.bump_type] ?? 9) - (bumpOrder[b.bump_type] ?? 9);
    })
    .map(u => {
      const gap = u.version_gap ?? 0;
      const bumpIcon = u.bump_type === 'major' ? '🔴 MAJOR'
                     : u.bump_type === 'minor' ? '🟡 minor'
                     : '🟢 patch';
      const critFlag = u.criticality === 'critical' ? ' ⚡' : '';
      const driftFlag = gap >= HIGH_DRIFT_THRESHOLD ? ` 🏚 drift:${gap}` : '';
      return `${bumpIcon}  ${u.display_name}${critFlag}${driftFlag}\n  ${u.current_version} → ${u.latest_version}`;
    })
    .join('\n\n');

  // Escalation: alta priorità anche quando c'è alto drift senza major bump
  const needsHighPriority = hasMajorOrCritical || hasHighDrift;

  notifications.push({
    title: `Homelab Updates - ${data.updates.length} aggiornamento/i disponibile/i`,
    priority: needsHighPriority ? 'high' : 'default',
    tags: needsHighPriority ? 'arrow_up,exclamation' : 'arrow_up',
    body: `🔄 Aggiornamenti disponibili (${runTime}):\n\n${lines}`
  });
}

// ── 4. SERVIZI NON CENSITI ────────────────────────────────────────────────────
if (data.untracked_warnings?.length > 0) {
  notifications.push({
    title: `Homelab - ${data.untracked_warnings.length} servizio/i non censiti`,
    priority: 'low',
    tags: 'memo',
    body: `📋 Servizi Docker non in services_metadata.json:\n\n${data.untracked_warnings.map(s => `• ${s}`).join('\n')}\n\nAggiungili al file per abilitare il tracking.`
  });
}

return notifications.map(n => ({ json: n }));

// Build Ollama prompt v5 — direct from parsed output, no Merge needed
const OLLAMA_MODEL = 'qwen2.5:7b';

const data = $input.first().json;
const updates = data.updates || [];

const services = updates.map(u => ({
  name: u.display_name || u.compose_name,
  current: u.current_version,
  latest: u.latest_version,
  bump: u.bump_type,
  criticality: u.criticality,
  gap: u.version_gap || 0,
  stack: u.stack_name,
}));

const systemPrompt = `You are an expert sysadmin specializing in Docker self-hosted homelab infrastructure.
You analyze container service updates and produce concise risk assessments.

For each service evaluate:
- Risk: "safe" (patch, bugfix) | "caution" (minor with possible behavioral changes) | "risky" (major bump, known breaking changes, large version gaps)
- Reason in 1-2 short sentences
- Pre-update actions needed (backup, migration, config review) or "none"

Then suggest an update order from safest to riskiest.

RULES:
- Do NOT think or reason out loud. Output ONLY valid JSON.
- No backticks, no markdown, no text before or after the JSON.
- Use this exact schema:
{
  "assessments": [
    { "service": "...", "risk": "safe|caution|risky", "reason": "...", "pre_actions": "none|..." }
  ],
  "update_order": ["service1", "service2"],
  "summary": "1-2 sentence overall summary"
}`;

const userPrompt = services.map(s =>
  `## ${s.name} [${s.criticality}] - stack: ${s.stack}\n` +
  `Version: ${s.current} -> ${s.latest}\n` +
  `Bump type: ${s.bump} | Gap: ${s.gap}`
).join('\n\n---\n\n');

const ollamaBody = {
  model: OLLAMA_MODEL,
  format: 'json',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  stream: false,
  options: { temperature: 0.1, num_predict: 2048 }
};

return [{ json: {
  service_count: services.length,
  service_names: services.map(s => s.name),
  system_prompt: systemPrompt,
  user_prompt: userPrompt,
  ollama_body: JSON.stringify(ollamaBody)
}}];

// Build AI notification v2
const raw = $input.first().json;
const content = raw?.message?.content || raw?.response || '';

let report;
try {
  const noThink = content.replace(/<think>[\s\S]*?<\/think>/g, '');
  // Estrae il primo blocco JSON valido
  const jsonMatch = noThink.match(/\{[\s\S]*\}/);
  const cleaned = jsonMatch ? jsonMatch[0] : noThink;
  report = JSON.parse(cleaned);
} catch (e) {
  return [{ json: {
    title: 'Homelab AI - Update analysis',
    priority: 'default',
    tags: 'robot_face',
    body: `Ollama response (unstructured):\n\n${content.substring(0, 1500) || 'No response from Ollama'}`,
  }}];
}

const riskEmoji = { safe: '🟢', caution: '🟡', risky: '🔴' };
const lines = (report.assessments || []).map(a => {
  const icon = riskEmoji[a.risk] || a.risk || '⚪';
  const preAct = a.pre_actions && a.pre_actions !== 'none' && a.pre_actions !== '-' ? `\n  ⚠ ${a.pre_actions}` : '';
  return `${icon}  ${a.service}\n  ${a.reason}${preAct}`;
}).join('\n\n');

const order = (report.update_order || []).join(' -> ');
const hasRed = (report.assessments || []).some(a => a.risk === 'risky');
const hasYellow = (report.assessments || []).some(a => a.risk === 'caution');

const body = [`AI update analysis:\n`, lines, `\nSuggested order:\n${order}`, report.summary ? `\n${report.summary}` : ''].filter(Boolean).join('\n');

return [{ json: {
  title: 'Homelab AI - Risk Assessment',
  priority: hasRed ? 'high' : hasYellow ? 'default' : 'low',
  tags: hasRed ? 'robot_face,warning' : 'robot_face',
  body
}}];
